-- Running revenue per month (from the materialized view)
SELECT month, orders, revenue,
       sum(revenue) OVER (ORDER BY month) AS running_total,
       rank() OVER (ORDER BY revenue DESC) AS rank_by_revenue
FROM monthly_revenue
ORDER BY month;

